    resource_id = register()
    for path in (
        "/resources//lifecycle",
        f"/resources/{resource_id}%2Fx/lifecycle",
        f"/resources/{resource_id}/lifecycle",
    ):
        query = "x=1" if path.endswith("/lifecycle") and resource_id in path else None
        if path == f"/resources/{resource_id}/lifecycle":
            status, _, body = call_json(
                "GET", path, query_string=query or "x=1"
            )
        else:
            status, _, body = call_json("GET", path)
        self.assertEqual(status, "400 Bad Request", body)
        self.assertEqual(body["error"], "invalid_request")

